import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
    except StopIteration:
        return

    matrix = []
    for _ in range(N):
        row = []
        for _ in range(N):
            row.append(int(next(iterator)))
        matrix.append(row)

    MOD = 10**9 + 7

    adj = [[] for _ in range(N * N)]
    degree = [0] * (N * N)

    def get_idx(r, c):
        return r * N + c

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    for r in range(N):
        for c in range(N):
            curr_val = matrix[r][c]
            curr_idx = get_idx(r, c)
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    neighbor_val = matrix[nr][nc]
                    if neighbor_val < curr_val:
                        neighbor_idx = get_idx(nr, nc)
                        adj[curr_idx].append(neighbor_idx)
                        degree[neighbor_idx] += 1

    dp = [1] * (N * N)
    queue = deque()

    for i in range(N * N):
        if degree[i] == 0:
            queue.append(i)

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            degree[v] -= 1
            if degree[v] == 0:
                queue.append(v)
            dp[v] = (dp[v] + dp[u]) % MOD

    total = sum(dp) % MOD
    print(total)

if __name__ == "__main__":
    main()
